'use strict';
const assert=require('node:assert/strict'),path=require('node:path'),root=path.resolve(__dirname,'..');
global.window=global;global.scrollY=0;global.requestAnimationFrame=fn=>{if(typeof fn==='function')fn();return 1};
global.localStorage={getItem(){return null},setItem(){},removeItem(){}};
global.document={readyState:'loading',addEventListener(){},querySelector(){return null},querySelectorAll(){return[]},body:{dataset:{}}};
global.location={hash:'',href:'https://repair.test/'};global.history={state:null,replaceState(){},pushState(){},back(){}};global.addEventListener=()=>{};global.removeEventListener=()=>{};
require(path.join(root,'app.js'));
require(path.join(root,'engines/parser-semantics.js'));
require(path.join(root,'engines/session-repair.js'));
const M=global.MSOS4,S=M.session,R=M.sessionRepair;
const src=`MAIN SET\n3 Rounds:\n  5 x 100 Threshold\n  200 Easy`;
const correct=M.parser.parse(src,{id:'persisted',date:'2026-08-24',dayPart:'PM',course:'SCM'});
assert.equal(S.total(correct),2100,'fresh parser truth must be 2100m');
const malformed=M.util.clone(correct),b=malformed.blocks[0],g=b.items[0],easy=g.items.pop();b.items.push(easy);
const thr=g.items[0];thr.restSeconds=10;malformed.changes=[{id:'c1',type:'edit_item',itemId:thr.id,before:{},after:{}},{id:'c2',type:'coach_change',itemId:null}];
malformed.originalPlan=correct.originalPlan;
malformed.currentSource={text:`MAIN SET\n3 Rounds:\n  5 x 100 Threshold\n200 Easy\nTOTAL 1700m`,hash:'old',updatedAt:'old'};
assert.equal(S.total(malformed),1700,'fixture must reproduce phone bug');
const fixed=R.repairPersistedRoundScope(malformed);
assert.ok(fixed,'persisted round repair must apply');
assert.equal(S.total(fixed),2100,'repaired persisted truth must be 2100m');
assert.equal(fixed.blocks[0].items.length,1,'200 Easy must return inside the round group');
assert.equal(fixed.blocks[0].items[0].items.length,2,'round group must contain both authored lines');
assert.equal(fixed.blocks[0].items[0].items[0].id,thr.id,'existing set identity must survive migration');
assert.equal(fixed.blocks[0].items[0].items[0].restSeconds,10,'existing live edit must survive migration');
assert.equal(fixed.changes.length,2,'existing change journal must survive migration');
assert.match(fixed.currentSource.text,/TOTAL 2100m/,'current source must be rewritten from repaired canonical truth');
assert.equal(fixed.metadata.repairReason,'persisted_round_scope');
const finished=M.util.clone(malformed);finished.finish={actualDistance:1700};assert.equal(R.repairPersistedRoundScope(finished),null,'finished historical sessions must not auto-mutate');
